CREATE SCHEMA IF NOT EXISTS "public";
CREATE TABLE "User" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "image" TEXT, "password" TEXT, "role" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Participant" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "isHost" BOOLEAN NOT NULL DEFAULT false, "joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "totalOwed" DOUBLE PRECISION NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Participant_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Receipt" ("id" UUID NOT NULL, "createdBy" UUID NOT NULL, "restaurant" TEXT NOT NULL DEFAULT '', "address" TEXT NOT NULL DEFAULT '', "items" JSONB NOT NULL DEFAULT '[]', "totalAmount" DOUBLE PRECISION NOT NULL, "imageUrl" TEXT NOT NULL DEFAULT '', "uploadedBy" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Receipt_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Split" ("id" UUID NOT NULL, "createdBy" UUID NOT NULL, "name" TEXT NOT NULL DEFAULT '', "receiptId" UUID, "splitType" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "breakdown" JSONB NOT NULL DEFAULT '[]', "payments" JSONB NOT NULL DEFAULT '[]', "totalAmount" DOUBLE PRECISION NOT NULL, "calculatedAt" TIMESTAMP(3), "finalizedAt" TIMESTAMP(3), "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Split_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "splitId" UUID NOT NULL, "participants" JSONB NOT NULL DEFAULT '[]', "qrCode" TEXT NOT NULL DEFAULT '', "startDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "endDate" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Group" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "members" TEXT[] DEFAULT ARRAY[]::TEXT[], "createdBy" UUID NOT NULL, "image" TEXT NOT NULL DEFAULT '', "splitId" UUID, "sessionId" UUID, "qrCode" TEXT NOT NULL DEFAULT '', "defaultCurrency" TEXT NOT NULL DEFAULT 'NPR', "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Group_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Nudge" ("id" UUID NOT NULL, "recipientName" TEXT NOT NULL, "recipientEmail" TEXT NOT NULL, "senderName" TEXT NOT NULL, "groupName" TEXT NOT NULL, "amount" DOUBLE PRECISION NOT NULL, "currency" TEXT NOT NULL DEFAULT 'NPR', "dueDate" TEXT NOT NULL DEFAULT 'soon', "payLink" TEXT NOT NULL DEFAULT '#', "paidByName" TEXT NOT NULL DEFAULT '', "status" TEXT NOT NULL DEFAULT 'pending', "errorMessage" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Nudge_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Transaction" ("id" UUID NOT NULL, "customerDetails" JSONB NOT NULL, "product_name" TEXT NOT NULL, "product_id" TEXT NOT NULL, "amount" DOUBLE PRECISION NOT NULL, "payment_gateway" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Transaction_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE INDEX "Participant_userId_idx" ON "Participant"("userId");
CREATE INDEX "Receipt_createdBy_idx" ON "Receipt"("createdBy");
CREATE INDEX "Split_createdBy_idx" ON "Split"("createdBy");
CREATE INDEX "Split_receiptId_idx" ON "Split"("receiptId");
CREATE UNIQUE INDEX "Session_splitId_key" ON "Session"("splitId");
CREATE INDEX "Group_createdBy_createdAt_idx" ON "Group"("createdBy", "createdAt");
CREATE INDEX "Group_isActive_idx" ON "Group"("isActive");
CREATE UNIQUE INDEX "Transaction_product_id_key" ON "Transaction"("product_id");
